insert into public.site_settings (key, value, label, hint, multiline, sort_order) values ('hours_note', 'Täglich ab 11 Uhr geöffnet, mit Ausnahme von Heiligabend. Am 1. und 2. Weihnachtsfeiertag nur bis 15:00 Uhr.', 'Hinweis unter den Öffnungszeiten', 'Erscheint unter der Tabelle mit den Öffnungszeiten, zum Beispiel für Feiertage.', true, 1);
insert into public.site_settings (key, value, label, hint, multiline, sort_order) values ('order_note', 'Alle Gerichte und Getränke auch zum Abholen und Mitnehmen! Aufgrund der aktuellen Situation sind ggf. nicht alle Gerichte verfügbar.', 'Hinweis zum Bestellen', 'Steht auf der Startseite und über der Speisekarte im grünen Kasten.', true, 2);
insert into public.site_settings (key, value, label, hint, multiline, sort_order) values ('menu_intro', 'Suppen, Vorspeisen, Eiergerichte, Nudelgerichte, Salate, Geflügelgerichte, Fleischgerichte, Pfannengerichte, Schnitzelparadies, Dessert und Eis, Knabberzeug, Kindergerichte und Spargelgerichte.', 'Einleitung der Speisekarte', 'Die Aufzählung der Kategorien oben auf der Seite „Speisekarte“.', true, 3);
insert into public.site_settings (key, value, label, hint, multiline, sort_order) values ('seasonal_menu_note', '…zur Osterzeit, …zur Spargelzeit, …zur Grünkohlzeit, …zur Weihnachtszeit. Lassen Sie sich überraschen!', 'Saisonkarte', 'Der Kasten „Hier steckt unsere Saisonkarte“ unter der Speisekarte.', true, 4);
