insert into public.site_settings (key, value, label, hint, multiline, sort_order) values ('events_intro', 'Wir beraten Sie gern und können Ihnen aus einem reichhaltigen Sortiment ein maßgeschneidertes Angebot erstellen. Sie brauchen sich nur zu entscheiden und die Feier kann starten, um den Rest kümmern wir uns!', 'Text zu Feiern & Catering', 'Erscheint auf den Seiten „Feiern & Catering“, „Galerie“ und „Kontakt“.', true, 7);
